-- Modify "email_outbox" table
ALTER TABLE "email_outbox" ADD CONSTRAINT "email_outbox_intent_check" CHECK (((kind = 'notification'::email_outbox_kind) AND (notification_id IS NOT NULL) AND (recipient_email IS NULL) AND (locale IS NULL) AND (action_url IS NULL)) OR ((kind = ANY (ARRAY['verify_email'::email_outbox_kind, 'reset_password'::email_outbox_kind])) AND (notification_id IS NULL) AND (((status = ANY (ARRAY['pending'::email_outbox_status, 'processing'::email_outbox_status])) AND (NULLIF(btrim(recipient_email), ''::text) IS NOT NULL) AND (NULLIF(btrim(action_url), ''::text) IS NOT NULL) AND (locale = ANY (ARRAY['zh'::text, 'en'::text, 'ja'::text, 'ko'::text, 'de'::text, 'fr'::text, 'es'::text]))) OR ((status = ANY (ARRAY['accepted'::email_outbox_status, 'failed'::email_outbox_status])) AND (recipient_email IS NULL) AND (locale IS NULL) AND (action_url IS NULL)))));
-- Modify "profile_preference" table
ALTER TABLE "profile_preference" ADD CONSTRAINT "profile_preference_interface_locale_check" CHECK (interface_locale = ANY (ARRAY['en'::text, 'zh-Hant'::text, 'zh-Hans'::text, 'ja'::text, 'ko'::text, 'de'::text, 'fr'::text, 'es'::text])), DROP CONSTRAINT "profile_preference_languages_check", ADD CONSTRAINT "profile_preference_languages_check" CHECK ((cardinality(preferred_languages) > 0) AND (preferred_languages <@ ARRAY['zh'::text, 'en'::text, 'ja'::text, 'ko'::text, 'de'::text, 'fr'::text, 'es'::text]) AND (cardinality(array_positions(preferred_languages, 'zh'::text)) <= 1) AND (cardinality(array_positions(preferred_languages, 'en'::text)) <= 1) AND (cardinality(array_positions(preferred_languages, 'ja'::text)) <= 1) AND (cardinality(array_positions(preferred_languages, 'ko'::text)) <= 1) AND (cardinality(array_positions(preferred_languages, 'de'::text)) <= 1) AND (cardinality(array_positions(preferred_languages, 'fr'::text)) <= 1) AND (cardinality(array_positions(preferred_languages, 'es'::text)) <= 1)), ADD CONSTRAINT "profile_preference_chinese_content_display_check" CHECK (chinese_content_display = ANY (ARRAY['original'::text, 'hant'::text, 'hans'::text])), ALTER COLUMN "interface_locale" SET DEFAULT 'zh-Hant', ADD COLUMN "chinese_content_display" text NOT NULL DEFAULT 'original';
-- Modify "realm_rule_acceptance" table
ALTER TABLE "realm_rule_acceptance" DROP CONSTRAINT "realm_rule_acceptance_language_check", ADD CONSTRAINT "realm_rule_acceptance_language_check" CHECK ((language IS NULL) OR (language = ANY (ARRAY['zh'::text, 'en'::text, 'ja'::text, 'ko'::text, 'de'::text, 'fr'::text, 'es'::text])));
-- Modify "unit_alias" table
