-- Modify "unit_revision_slot" table
ALTER TABLE "unit_revision_slot" DROP CONSTRAINT "unit_revision_slot_key_shape_check", ADD CONSTRAINT "unit_revision_slot_key_shape_check" CHECK (((role = 'localization'::unit_revision_slot_role) AND (slot_key = ANY (ARRAY['zh'::text, 'en'::text, 'ja'::text, 'ko'::text, 'de'::text, 'fr'::text, 'es'::text]))) OR ((role <> 'localization'::unit_revision_slot_role) AND (slot_key = ''::text)));
